sql_query:
SELECT portfolio_health_id, investor_id, risk_score, diversification_score
            FROM ATOM_ENTITY_PORTFOLIO_HEALTH_001
            WHERE risk_score > 80 AND diversification_score < 20;

SELECT segment, category, COUNT(*) AS investor_count
            FROM ATOM_ENTITY_INVESTOR_PROFILE_001
            GROUP BY segment, category;

SELECT logic, action, COUNT(*) AS record_count
            FROM ATOM_EVENT_REBALANCING_ACTION_001
            GROUP BY logic, action;
